        while c<W:
            if g[r][c]!=bg:
                c0=c
                while c<W and g[r][c]==g[r][c0]: c+=1
                if c-c0>=2: hbar.append((r,c0,c-1))
            else: c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]!=bg:
                r0=r
                while r<H and g[r][c]==g[r0][c]: r+=1
                if r-r0>=2: vbar.append((c,r0,r-1))
    seeds=[(rr,cc,g[rr][cc]) for rr in range(H) for cc in range(W) if g[rr][cc]!=bg and not any(rr==br[0] and br[1]<=cc<=br[2] for br in hbar) and not any(cc==bv[0] and bv[1]<=rr<=bv[2] for bv in vbar)]
    print('hbar',hbar,'vbar',vbar,'seeds',seeds)
    # rays from bar endpoints inward; direction chosen = towards grid center roughly / along bar's perpendicular
    def trace(r0,c0,dr,dc,stopval=None):
        r,c=r0,c0
